gMG(){return"\u06a9\u0633\u0679\u0645\u0631\u0632\u060c \u0627\u0646\u0648\u0627\u0626\u0633\u0632\u060c \u0627\u0648\u0631 \u06a9\u0645\u06cc\u0634\u0646 \u0631\u06cc\u0679\u0633 \u067e\u0631 \u067e\u0631\u0627\u0646\u06d2 \u0633\u06cc\u0644\u0632\u0645\u06cc\u0646 \u0646\u0627\u0645\u0648\u06ba \u06a9\u0648 \u0627\u06cc\u06a9 \u062d\u0642\u06cc\u0642\u06cc \u0627\u0633\u0679\u0627\u0641 \u0627\u06a9\u0627\u0624\u0646\u0679 \u0633\u06d2 \u0645\u0646\u0633\u0644\u06a9 \u06a9\u0631\u06cc\u06ba"},
gMn(){return"\u062d\u0630\u0641 \u0634\u062f\u06c1 \u0644\u06cc\u0646 \u062f\u06cc\u0646"},
gMm(){return"\u06c1\u0631 \u062d\u0630\u0641 \u0634\u062f\u06c1 \u0627\u0646\u0648\u0627\u0626\u0633\u060c \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0627\u0646\u0648\u0627\u0626\u0633\u060c \u06a9\u0631\u06cc\u0688\u0679/\u0688\u06cc\u0628\u0679 \u0646\u0648\u0679 \u0627\u0648\u0631 \u0686\u06cc\u06a9 \u2014 \u06a9\u0633 \u0646\u06d2 \u062d\u0630\u0641 \u06a9\u06cc\u0627\u060c \u0627\u0648\u0631 \u06a9\u0628"},
gRk(){return"\u06cc\u06c1 \u0688\u06cc\u0648\u0627\u0626\u0633 \u0641\u0646\u06af\u0631 \u067e\u0631\u0646\u0679 \u06cc\u0627 \u0641\u06cc\u0633 \u0627\u0646 \u0644\u0627\u06a9 \u06a9\u0648 \u0633\u067e\u0648\u0631\u0679 \u0646\u06c1\u06cc\u06ba \u06a9\u0631\u062a\u06cc\u06d4"},
