gSp(){return"\u06a9\u0645\u0631\u0634\u0644 \u0631\u062c\u0633\u0679\u0631\u06cc\u0634\u0646 (CR) \u0646\u0645\u0628\u0631"},
gSN(){return"\u0648\u06cc\u0628 \u0633\u0627\u0626\u0679"},
gSl(){return"\u0628\u0646\u06cc\u0627\u062f\u06cc \u06a9\u0631\u0646\u0633\u06cc"},
gSD(){return"\u067e\u0631\u06cc\u0641\u06a9\u0633"},
