gSd(){return"\u0627\u06a9\u0627\u0624\u0646\u0679 \u0679\u0627\u0626\u0679\u0644"},
gSc(){return"\u0627\u06a9\u0627\u0624\u0646\u0679 \u0646\u0645\u0628\u0631"},
gSe(){return"\u0627\u06a9\u0627\u0624\u0646\u0679 \u06a9\u06cc \u0642\u0633\u0645"},
gSx(){return"IBAN"},
gSj(){return"\u0628\u06cc\u0646\u06a9 \u06a9\u0627 \u0646\u0627\u0645"},
