gGC(){return"\u0679\u06cc\u06af \u0644\u0627\u0626\u0646 \u0631\u0646\u06af"},
gSI(){return"\u06c1\u0631 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u067e\u0631 \u0622\u067e \u06a9\u06d2 \u0646\u0627\u0645 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u067e\u0631\u0646\u0679 \u06c1\u0648\u062a\u0627 \u06c1\u06d2"},
gSH(){return"\u0622\u067e \u06a9\u06d2 \u067e\u0631\u0646\u0679 \u0634\u062f\u06c1 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632\u0627\u062a \u067e\u0631 \u06c1\u0631 \u0679\u06cc\u0628\u0644/\u0628\u0627\u06a9\u0633 \u0628\u0627\u0631\u0688\u0631 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0628\u06be\u06cc \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u2014 \u067e\u0631\u0646\u0679 \u0644\u06d2 \u0622\u0624\u0679 \u062e\u0648\u062f \u06a9\u0628\u06be\u06cc \u0646\u06c1\u06cc\u06ba \u0628\u062f\u0644\u062a\u0627\u060c \u0635\u0631\u0641 \u06cc\u06c1 \u0627\u06cc\u06a9 \u0631\u0646\u06af\u06d4"},
