gNj(){return"\u0648\u06c1 \u0627\u0628 \u0627\u0633 \u0688\u06cc\u0648\u0627\u0626\u0633 \u067e\u0631 \u0633\u0627\u0626\u0646 \u0627\u0646 \u0646\u06c1\u06cc\u06ba \u06a9\u0631 \u0633\u06a9\u06cc\u06ba \u06af\u06d2\u06d4 \u0627\u0646\u06c1\u0648\u06ba \u0646\u06d2 \u062c\u0648 \u06a9\u0686\u06be \u0628\u06be\u06cc \u0628\u0646\u0627\u06cc\u0627 \u06c1\u06d2 \u06cc\u0627 \u062c\u0648 \u0627\u0646\u06c1\u06cc\u06ba \u062a\u0641\u0648\u06cc\u0636 \u06a9\u06cc\u0627 \u06af\u06cc\u0627 \u06c1\u06d2 \u2014 \u0627\u0646\u0648\u0627\u0626\u0633\u0632\u060c \u0688\u06cc\u0644\u06cc\u0648\u0631\u06cc\u0632\u060c \u0644\u06cc\u062c\u0631 \u0627\u0646\u062f\u0631\u0627\u062c\u0627\u062a \u2014 \u0628\u0627\u0644\u06a9\u0644 \u0648\u06cc\u0633\u06d2 \u06c1\u06cc \u0631\u06c1\u06cc\u06ba \u06af\u06d2\u060c \u062f\u0631\u0633\u062a \u0637\u0648\u0631 \u067e\u0631 \u0627\u0646 \u0633\u06d2 \u0645\u0646\u0633\u0648\u0628\u06d4 \u0627\u0633\u06d2 \u06cc\u06c1\u0627\u06ba \u0633\u06d2 \u0648\u0627\u067e\u0633 \u0646\u06c1\u06cc\u06ba \u06a9\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u061b \u0627\u06af\u0631 \u0648\u06c1 \u0648\u0627\u067e\u0633 \u0622\u0626\u06cc\u06ba \u062a\u0648 \u0627\u0646\u06c1\u06cc\u06ba \u0646\u0626\u06d2 \u0679\u06cc\u0645 \u0645\u0645\u0628\u0631 \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0634\u0627\u0645\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u0648 \u06a9\u06c1\u06cc\u06ba\u06d4"},
Nm(a){return a+" \u06c1\u0679\u0627 \u062f\u06cc\u0627 \u06af\u06cc\u0627\u06d4"},
Nl(a,b){return a+" \u06a9\u0648 \u06c1\u0679\u0627\u06cc\u0627 \u0646\u06c1\u06cc\u06ba \u062c\u0627 \u0633\u06a9\u0627: "+b},
gAW(){return"\u06c1\u0679\u0627\u0626\u06cc\u06ba"},
gNd(){return"\u06a9\u0648\u0626\u06cc \u0641\u0648\u0646 \u0646\u06c1\u06cc\u06ba"},
gNq(){return"\u067e\u0646 \u0631\u06cc \u0633\u06cc\u0679 \u06a9\u0631\u06cc\u06ba"},
gN6(){return"\u0627\u06cc\u0688\u0645\u0646 \u0631\u0633\u0627\u0626\u06cc"},
gN5(){return"\u067e\u0648\u0633\u0679 \u0634\u062f\u06c1 \u0627\u0646\u0648\u0627\u0626\u0633\u0632\u060c \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc\u060c \u0627\u0648\u0631 \u0648\u0627\u0624\u0686\u0631\u0632 \u0645\u06cc\u06ba \u062a\u0631\u0645\u06cc\u0645 \u0627\u0648\u0631 \u062d\u0630\u0641 \u06a9\u0631 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u2014 \u0639\u0627\u0645 \u0637\u0648\u0631 \u067e\u0631 \u0635\u0631\u0641 \u0645\u0627\u0644\u06a9 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4"},
gNa(){return"\u0679\u06cc\u0645 \u0645\u0645\u0628\u0631 \u0645\u06cc\u06ba \u062a\u0631\u0645\u06cc\u0645 \u06a9\u0631\u06cc\u06ba"},
