gNz(){return"\u0627\u0628\u062a\u062f\u0627\u0626\u06cc \u067e\u0646 (4+ \u06c1\u0646\u062f\u0633\u06d2)"},
gNy(){return"\u0648\u06c1 \u0633\u0627\u0626\u0646 \u0627\u0646 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06cc\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u06cc\u06ba \u06af\u06d2 \u2014 \u0627\u0633 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0627\u0646\u06c1\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0628\u0646\u0627\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4"},
